   $$natuurkunde-vwo-2025-i-h-alfafilter-vraag21.png$$, $$Bepaal de temperatuur van de fotosfeer volgens figuur 1.$$, array['6b73bf69-7db7-4615-9f11-a0c43bfb382d']::uuid[]),
  ('cda1b700-1198-44b9-a27b-1da22ad1f1f5', 'f224a412-ebf8-4ac7-aa37-12c23b82fbf7', 22,
